    "seoTitle": "How Many Photography Clients Per Month?",
    "description": "Learn how many photography clients per month you need to break even, pay yourself, and profit—using contribution, capacity, travel, and seasonality.",
    "metaDescription": "Learn how many photography clients per month you need to break even, pay yourself, and profit—using contribution, capacity, travel, and seasonality.",
    "image": "/images/blog/day4-photography-clients.webp",
    "alt": "Photography business owner planning customer volume and weekly capacity",
    "imageCaption": "Photography business owner planning customer volume and weekly capacity",
    "calculatorSlug": "photography-business-break-even-calculator",
    "published": "2026-09-22",
