    "cluster": "volume-to-income",
    "title": "How Many Detailing Jobs Per Week to Go Full Time?",
    "seoTitle": "How Many Detailing Jobs Per Week to Go Full Time",
    "description": "Learn how many detailing jobs per week you need to cover owner pay, overhead, taxes, and capacity limits with practical mobile detailing examples.",
    "metaDescription": "Learn how many detailing jobs per week you need to cover owner pay, overhead, taxes, and capacity limits with practical mobile detailing examples.",
    "image": "/images/blog/day4-detailing-jobs.webp",
    "alt": "Mobile detailing business owner planning customer volume and weekly capacity",
    "imageCaption": "Mobile detailing business owner planning customer volume and weekly capacity",
    "calculatorSlug": "mobile-detailing-break-even-calculator",
    "published": "2026-09-22",
